import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.airscale.genericairscale import GenericAirscale


class Confmgmtbrowser(GenericAirscale):
    """Confmgmtbrowser command class."""

    def __init__(self, connection, mode, parameter=None, value=None, prompt=None, newline_chars=None, runner=None):
        """
        Adet command checks all board status of gNB.

        :param connection: moler connection to device, terminal when command is executed
        :param mode: read, read_domain or write option to choose
        :param parameter: parameter defined to read or write
        :param value: parameter value to write
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Confmgmtbrowser, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.mode = mode
        self.parameter = parameter
        self.value = value
        self.current_ret["RESULT"] = []
        self.tmp_dict = {}

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"confmgmtbrowser {self.mode} ip_mgmt"

        cmd = f"{cmd} {self.parameter}" if self.parameter else cmd
        cmd = f"{cmd} {self.value}" if self.value else cmd

        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Parse received line to get expected value.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_read_command(line)
                self._parse_empty_line(line)
            except ParsingDone:
                pass
        return super(Confmgmtbrowser, self).on_new_line(line, is_full_line)

    # regex to find expected DOMAIN, KEY and VALUE of parameter, eg.:
    # DOMAIN: ip_mgmt
    # KEY: link_meas_window_len
    # VALUE: 1
    _re_read_command_output = re.compile(r"(?P<KEY>\w+):\s*(?P<VALUE>.+)")

    def _parse_read_command(self, line):
        """
        Parse output of read command to extract DOMAIN, KEY and VALUE.

        :param line: output of command
        :return: None but raises ParsingDone if line has DOMAIN, KEY and VALUE of parameter.
        """
        if self._regex_helper.search_compiled(Confmgmtbrowser._re_read_command_output, line):
            self.tmp_dict.update({self._regex_helper.group("KEY"): self._regex_helper.group("VALUE")})
            raise ParsingDone

    def _parse_empty_line(self, line):
        """
        Check if the given line is empty.

        :param line: output of command
        :return: None but raises ParsingDone if line is empty.
        """
        if line == "":
            self.current_ret["RESULT"].append(self.tmp_dict)
            self.tmp_dict = {}
            raise ParsingDone


